export function parseCSV(text) {
  if (typeof text !== 'string') throw Error('CSV must be text');
  if (!text.length) return [];
  const rows = []; let row = [], field = '', state = 'plain', started = false;
  const fieldEnd = () => { row.push(field); field = ''; state = 'plain'; };
  for (let i = 0; i < text.length; i++) {
    const c = text[i]; started = true;
    if (state === 'quoted') {
      if (c === '"') {
        if (text[i + 1] === '"') { field += '"'; i++; }
        else state = 'closed';
      } else field += c;
      continue;
    }
    if (c === ',') { fieldEnd(); continue; }
    if (c === '\n' || c === '\r') {
      if (c === '\r' && text[i + 1] === '\n') i++;
      fieldEnd(); rows.push(row); row = []; started = false; continue;
    }
    if (state === 'closed') throw Error('Unexpected character after quote');
    if (c === '"') {
      if (field.length) throw Error('Quote in unquoted field');
      state = 'quoted';
    } else field += c;
  }
  if (state === 'quoted') throw Error('Unclosed quote');
  if (started) { fieldEnd(); rows.push(row); }
  return rows;
}

export function stringifyCSV(rows) {
  return rows.map(row => row.map(value => {
    if (typeof value !== 'string') throw Error('CSV values must be strings');
    return /[",\r\n]/.test(value) ? `"${value.replaceAll('"', '""')}"` : value;
  }).join(',')).join('\r\n');
}

export function parseVersion(text) {
  if (typeof text !== 'string' || !/^(0|[1-9][0-9]*)\.(0|[1-9][0-9]*)\.(0|[1-9][0-9]*)(?:-([A-Za-z0-9-]+(?:\.[A-Za-z0-9-]+)*))?$/.test(text)) throw Error('Invalid version');
  const match = text.match(/^(\d+)\.(\d+)\.(\d+)(?:-(.*))?$/);
  const prerelease = match[4] ? match[4].split('.') : [];
  if (prerelease.some(p => /^\d+$/.test(p) && p.length > 1 && p[0] === '0')) throw Error('Invalid version');
  return {major: Number(match[1]), minor: Number(match[2]), patch: Number(match[3]), prerelease};
}
export function compareVersions(a, b) {
  const left = parseVersion(a), right = parseVersion(b);
  // Compare the original integer strings to avoid precision loss for large versions.
  const integerCompare = (x, y) => x.length === y.length ? (x === y ? 0 : x < y ? -1 : 1) : x.length < y.length ? -1 : 1;
  const aa = a.split('-')[0].split('.'), bb = b.split('-')[0].split('.');
  for (let i = 0; i < 3; i++) { const c = integerCompare(aa[i], bb[i]); if (c) return c; }
  const ap = left.prerelease, bp = right.prerelease;
  if (!ap.length || !bp.length) return ap.length === bp.length ? 0 : ap.length ? -1 : 1;
  for (let i = 0; i < Math.min(ap.length, bp.length); i++) {
    const x = ap[i], y = bp[i]; if (x === y) continue;
    const xn = /^\d+$/.test(x), yn = /^\d+$/.test(y);
    return xn && yn ? integerCompare(x, y) : xn !== yn ? xn ? -1 : 1 : x < y ? -1 : 1;
  }
  return ap.length === bp.length ? 0 : ap.length < bp.length ? -1 : 1;
}

import {parseVersion} from './version.mjs';
const copy = value => structuredClone(value);
const object = value => value !== null && typeof value === 'object' && !Array.isArray(value);
export function normalizeRecord(record) {
  if (!object(record)) throw Error('Invalid record');
  const {id, name, version, tags, dependencies} = record;
  if (typeof id !== 'string' || !id.trim() || typeof name !== 'string' || !name.trim()) throw Error('Invalid id/name');
  parseVersion(version);
  if (!Array.isArray(tags) || tags.some(t => typeof t !== 'string') || !Array.isArray(dependencies) || dependencies.some(d => typeof d !== 'string' || !d.length)) throw Error('Invalid tags/dependencies');
  return {id: id.trim(), name: name.trim(), version, tags: [...new Set(tags.map(t => t.trim().toLowerCase()).filter(Boolean))].sort(), dependencies: [...new Set(dependencies)]};
}
export function createCatalog(seed = []) {
  if (!Array.isArray(seed)) throw Error('Invalid seed');
  let entries = new Map();
  function addTo(map, record) {
    const r = normalizeRecord(record);
    if (map.has(r.id)) throw Error(`Duplicate id: ${r.id}`);
    map.set(r.id, r); return copy(r);
  }
  for (const r of seed) addTo(entries, r);
  function updateIn(map, id, patch) {
    if (!map.has(id)) throw Error(`Unknown id: ${id}`);
    if (!object(patch) || (Object.hasOwn(patch, 'id') && patch.id !== id)) throw Error('Invalid patch/id change');
    const r = normalizeRecord({...map.get(id), ...patch}); map.set(id, r); return copy(r);
  }
  return {
    list: () => [...entries.values()].sort((a,b) => a.id < b.id ? -1 : a.id > b.id ? 1 : 0).map(copy),
    get: id => entries.has(id) ? copy(entries.get(id)) : null,
    add: record => addTo(entries, record),
    update: (id, patch) => updateIn(entries, id, patch),
    remove: id => entries.delete(id),
    applyBatch(operations) {
      if (!Array.isArray(operations)) throw Error('Invalid operations');
      const next = new Map(entries);
      const results = operations.map(op => {
        if (!object(op)) throw Error('Invalid operation');
        if (op.type === 'add') return addTo(next, op.record);
        if (op.type === 'update' && typeof op.id === 'string') return updateIn(next, op.id, op.patch);
        if (op.type === 'remove' && typeof op.id === 'string') return next.delete(op.id);
