  const nodes = new Map(records.map(r => [r.id,r])), done = new Set(), active = [], result = [];
  function visit(id) {
    if (!nodes.has(id)) throw Error(`Missing id: ${id}`);
    if (done.has(id)) return;
    const cycle = active.indexOf(id);
    if (cycle !== -1) throw Error(`Cycle: ${[...active.slice(cycle),id].join(' -> ')}`);
    active.push(id);
    for (const dependency of nodes.get(id).dependencies) visit(dependency);
    active.pop(); done.add(id); result.push(id);
  }
  for (const id of requestedIds) visit(id);
  return result;
}
export function reverseDependencies(records, id) {
  if (!records.some(r => r.id === id)) throw Error(`Unknown id: ${id}`);
  const reverse = new Map();
  for (const r of records) for (const dep of r.dependencies) {
    if (!reverse.has(dep)) reverse.set(dep, []);
    reverse.get(dep).push(r.id);
  }
  const seen = new Set([id]), pending = [id];
  while (pending.length) for (const dependent of reverse.get(pending.pop()) ?? []) {
    if (!seen.has(dependent)) { seen.add(dependent); pending.push(dependent); }
  }
  seen.delete(id); return [...seen].sort();
}

import {StringDecoder} from 'node:string_decoder';
import {parseCSV, stringifyCSV} from './csv.mjs';
const header = ['id','name','version','tags','dependencies'];
export function exportCSV(records) {
  return stringifyCSV([header, ...records.map(r => [r.id,r.name,r.version,r.tags.join('|'),r.dependencies.join('|')])]);
}
export function importCSV(text, catalog) {
  const rows = parseCSV(text);
  if (!rows.length || rows[0].length !== 5 || rows[0].some((v,i) => v !== header[i])) throw Error('Invalid CSV header');
  const records = rows.slice(1).map(row => {
    if (row.length !== 5) throw Error('Invalid CSV row');
    const [id,name,version,tags,dependencies] = row;
    return {id,name,version,tags: tags ? tags.split('|') : [],dependencies: dependencies ? dependencies.split('|') : []};
  });
  return catalog.applyBatch(records.map(record => ({type:'add',record})));
}
export async function* exportNDJSON(records) {
  for (const record of records) yield JSON.stringify(record) + '\n';
}
export async function importNDJSON(chunks, catalog) {
  const decoder = new StringDecoder('utf8'), records = []; let pending = '';
  function consume(text) {
    pending += text;
    let end;
    while ((end = pending.indexOf('\n')) !== -1) {
      const line = pending.slice(0,end); pending = pending.slice(end + 1);
      if (line.trim()) records.push(JSON.parse(line));
    }
  }
  for await (const chunk of chunks) {
    if (Buffer.isBuffer(chunk)) consume(decoder.write(chunk));
    else if (typeof chunk === 'string') { consume(decoder.end()); consume(chunk); }
    else throw Error('Invalid NDJSON chunk');
  }
  consume(decoder.end());
  if (pending.trim()) records.push(JSON.parse(pending));
  return catalog.applyBatch(records.map(record => ({type:'add',record})));
}

import http from 'node:http';
import {pathToFileURL} from 'node:url';
import {createCatalog} from './catalog.mjs';
import {searchRecords} from './search.mjs';
import {planDependencies} from './graph.mjs';
import {exportCSV, importCSV, exportNDJSON, importNDJSON} from './transfer.mjs';
const MAX_BODY = 1024 * 1024;
function failure(message, status = 400) { return Object.assign(Error(message), {status}); }
function readBody(req) {
  return new Promise((resolve,reject) => {
    const chunks = []; let size = 0, oversized = false;
    req.on('data', chunk => {
      size += chunk.length;
      if (size > MAX_BODY) {
        if (!oversized) { oversized = true; chunks.length = 0; reject(failure('Request body exceeds 1 MiB',413)); }
      } else if (!oversized) chunks.push(chunk);
    });
    req.on('end', () => { if (!oversized) resolve(Buffer.concat(chunks)); });
    req.on('error', reject);
    req.on('aborted', () => reject(failure('Request aborted')));
  });
}
export function createServer(catalog) {
  return http.createServer((req,res) => {
    const send = (status, value, type = 'application/json') => {
      res.writeHead(status, {'Content-Type': type});
      res.end(status === 204 ? undefined : type === 'application/json' ? JSON.stringify(value) : value);
    };
    async function handle() {
      const url = new URL(req.url, 'http://localhost'), path = url.pathname, method = req.method;
      if (method === 'GET' && path === '/health') return send(200,{ok:true});
      if (path === '/records') {
        if (method === 'GET') {
          const query = {};
          for (const key of ['text','versionMin','versionMax','sortBy','order']) if (url.searchParams.has(key)) query[key] = url.searchParams.get(key);
          if (url.searchParams.has('tags')) query.tags = url.searchParams.get('tags').split(',');
          for (const key of ['offset','limit']) if (url.searchParams.has(key)) {
            const value = url.searchParams.get(key);
            if (!/^\d+$/.test(value)) throw failure('Invalid paging');
            query[key] = Number(value);
          }
          return send(200,searchRecords(catalog.list(),query));
        }
        if (method === 'POST') {
          const record = JSON.parse((await readBody(req)).toString('utf8'));
          try { return send(201,catalog.add(record)); }
          catch (error) { if (/duplicate/i.test(error.message)) error.status = 409; throw error; }
        }
      }
      const match = path.match(/^\/records\/([^/]+)$/);
      if (match && ['GET','PATCH','DELETE'].includes(method)) {
        const id = decodeURIComponent(match[1]);
        if (!catalog.get(id)) throw failure(`Unknown id: ${id}`,404);
        if (method === 'GET') return send(200,catalog.get(id));
        if (method === 'PATCH') return send(200,catalog.update(id,JSON.parse((await readBody(req)).toString('utf8'))));
        catalog.remove(id); return send(204);
      }
      if (method === 'GET' && path === '/plan') {
        const ids = url.searchParams.get('ids');
        if (ids === null) throw failure('Missing ids');
        return send(200,{ids:planDependencies(catalog.list(),ids ? ids.split(',') : [])});
      }
      if (method === 'GET' && path === '/export.csv') return send(200,exportCSV(catalog.list()),'text/csv');
      if (method === 'POST' && path === '/import.csv') return send(201,{added:importCSV((await readBody(req)).toString('utf8'),catalog).length});
      if (method === 'POST' && path === '/import.ndjson') {
        const body = await readBody(req);
        return send(201,{added:(await importNDJSON([body],catalog)).length});
      }
      if (method === 'GET' && path === '/export.ndjson') {
        let text = ''; for await (const line of exportNDJSON(catalog.list())) text += line;
        return send(200,text,'application/x-ndjson');
      }
      throw failure('Not found',404);
    }
    handle().catch(error => {
      if (!res.headersSent && !res.destroyed) send(error.status ?? 400,{error:error.message});
      else if (!res.destroyed) res.end();
    });
  });
}
if (process.argv[1] && import.meta.url === pathToFileURL(process.argv[1]).href) {
  createServer(createCatalog()).listen(Number(process.env.PORT ?? 3000));
}

import {readFile, writeFile, rename, unlink} from 'node:fs/promises';
import {randomUUID} from 'node:crypto';
import {pathToFileURL} from 'node:url';
import {createCatalog} from './catalog.mjs';
import {searchRecords} from './search.mjs';
import {planDependencies} from './graph.mjs';
import {importCSV, exportCSV} from './transfer.mjs';
export async function runCLI(args) {
  const [command, ...rest] = args;
  const allowed = {
    list:['text','tags'], add:['record'], remove:['id'], plan:['ids'], 'import-csv':['input'], 'export-csv':[]
  };
  if (!Object.hasOwn(allowed,command)) throw Error('Unknown command');
  const options = {};
  for (let i = 0; i < rest.length; i += 2) {
    const flag = rest[i], value = rest[i+1];
    if (!flag.startsWith('--') || value === undefined || !['file',...allowed[command]].includes(flag.slice(2)) || Object.hasOwn(options,flag.slice(2))) throw Error(`Invalid option: ${flag}`);
    options[flag.slice(2)] = value;
  }
  if (!options.file) throw Error('--file is mandatory');
  const requireOption = key => { if (!options[key]) throw Error(`--${key} is mandatory`); return options[key]; };
  let seed;
  try { seed = JSON.parse(await readFile(options.file,'utf8')); }
  catch (error) { if (error.code !== 'ENOENT') throw error; seed = []; }
  const catalog = createCatalog(seed); let result, changed = false;
  switch (command) {
    case 'list': result = searchRecords(catalog.list(),{text:options.text ?? '',tags:options.tags ? options.tags.split(',') : []}); break;
    case 'add': result = catalog.add(JSON.parse(requireOption('record'))); changed = true; break;
    case 'remove': result = catalog.remove(requireOption('id')); changed = true; break;
    case 'plan': result = {ids:planDependencies(catalog.list(),requireOption('ids').split(','))}; break;
    case 'import-csv': result = {added:importCSV(await readFile(requireOption('input'),'utf8'),catalog).length}; changed = true; break;
    case 'export-csv': result = exportCSV(catalog.list()); break;
  }
  if (changed) {
    const temporary = `${options.file}.${randomUUID()}.tmp`;
    try {
      await writeFile(temporary,JSON.stringify(catalog.list(),null,2) + '\n',{flag:'wx'});
      await rename(temporary,options.file);
    } finally { await unlink(temporary).catch(error => { if (error.code !== 'ENOENT') throw error; }); }
  }
  return command === 'export-csv' ? result : JSON.stringify(result);
}
if (process.argv[1] && import.meta.url === pathToFileURL(process.argv[1]).href) {
  runCLI(process.argv.slice(2)).then(output => { process.stdout.write(output + '\n'); }).catch(error => {
    process.stderr.write(error.message + '\n'); process.exitCode = 1;
  });
}

import test from 'node:test';
import assert from 'node:assert/strict';
import {mkdtemp, readFile, writeFile, rm, readdir} from 'node:fs/promises';
